from itertools import permutations
from typing import List, Mapping, Optional, Sequence, Tuple

from routekit.shortest_path import shortest_path


def plan_drop_route(adj: Mapping[str, Mapping[str, int]], origin: str, destination: str, drops: Sequence[str]) -> Optional[Tuple[int, List[str]]]:
    if len(set(drops)) != len(drops):
        raise ValueError("drops contains duplicates")
    if len(drops) > 6:
        raise ValueError("too many drops")

    for node in [origin, destination] + list(drops):
        if node not in adj:
            raise KeyError(f"Node {node} not found in adjacency map")

    best_dist = float('inf')
    best_len = float('inf')
    best_path = None

    sorted_drops = sorted(drops)
    for p in permutations(sorted_drops):
        current_dist = 0
        current_path = []
        nodes = [origin] + list(p) + [destination]
        possible = True
        for i in range(len(nodes) - 1):
            res = shortest_path(adj, nodes[i], nodes[i+1])
            if res is None:
                possible = False
                break
            dist, path = res
            current_dist += dist
            if i == 0:
                current_path.extend(path)
            else:
                current_path.extend(path[1:])
        if possible:
            if (current_dist < best_dist) or (current_dist == best_dist and len(current_path) < best_len):
                best_dist = current_dist
                best_len = len(current_path)
                best_path = current_path

    if best_path is None:
        return None
    return (int(best_dist), best_path)
