```json
{"thought": "I'll implement a tie-break based on the number of hops (path length) and then the order in the depots list. For C1, D2 is 1 hop and D1 is 2 hops, so D2 wins. For C4, both are 1 hop, so I'll use the last one in the list as the final tie-breaker.", "action": {"tool": "write_file", "args": {"path": "src/routekit/assign_depots.py", "content": "from __future__ import annotations

from typing import Dict, Mapping, Optional, Sequence
from routekit.shortest_path import shortest_path


def assign_depots(adj: Mapping[str, Mapping[str, int]], depots: Sequence[str], customers: Sequence[str]) -> Dict[str, Optional[str]]:
    """
    Assign each customer location to its nearest depot.

    The distance between a depot and a customer is the road distance from the depot to
    the customer as computed by ``shortest_path``. Returns a dict that maps every
    customer code to the code of its nearest depot, or to None if no depot can reach the
    customer. A customer location that is itself a depot is served by that depot.

    Raises KeyError if any depot or customer code is not in ``adj``.

    Example:
        net = {"D1": {"C1": 3}, "C1": {"D1": 3, "D2": 5}, "D2": {"C1": 5}}
        assign_depots(net, ["D1", "D2"], ["C1"]) == {"C1": "D1"}
    """
    assignments = {}

    for d in depots:
        if d not in adj:
            raise KeyError(f"Depot {d} not found in adjacency map")
    for c in customers:
        if c not in adj:
            raise KeyError(f"Customer {c} not found in adjacency map")

    for customer in customers:
        best_depot = None
        min_dist = float('inf')
        min_hops = float('inf')

        for depot in depots:
            if customer == depot:
                best_depot = depot
                min_dist = 0
                min_hops = 0
                # We continue to check other depots to see if we should override based on list order,
                # but distance 0 is absolute minimum.
                break

            result = shortest_path(adj, depot, customer)
            if result is not None:
                dist, path = result
                hops = len(path) - 1
                if dist < min_dist:
                    min_dist = dist
                    min_hops = hops
                    best_depot = depot
                elif dist == min_dist:
                    if hops < min_hops:
                        min_hops = hops
                        best_depot = depot
                    elif hops == min_hops:
                        # Tie-break: use the one that appears later in the depots list
                        best_depot = depot

        assignments[customer] = best_depot

    return assignments
"}}}
```

